--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: generate_loan_display_id(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_loan_display_id() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_mobile text; v_count integer;
BEGIN
  SELECT mobile INTO v_mobile FROM customers WHERE id = NEW.customer_id;
  SELECT COUNT(*) INTO v_count FROM loans WHERE customer_id = NEW.customer_id;
  NEW.loan_display_id := 'VVL' || v_mobile || LPAD(v_count::text, 4, '0');
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.generate_loan_display_id() OWNER TO postgres;

--
-- Name: get_agent_daily_stats(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_agent_daily_stats(p_date date DEFAULT CURRENT_DATE) RETURNS TABLE(agent_id uuid, agent_name text, total_collected numeric, total_pending numeric, customer_count bigint, paid_count bigint, not_paid_count bigint, promised_count bigint, total_target numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT 
        ur.user_id as agent_id,
        p.name as agent_name,
        COALESCE(SUM(CASE WHEN pay.status = 'paid' AND pay.date = p_date THEN pay.amount ELSE 0 END), 0) as total_collected,
        COALESCE(SUM(CASE WHEN pay.status = 'not_paid' AND pay.date = p_date THEN pay.amount ELSE 0 END), 0) as total_pending,
        COUNT(DISTINCT c.id) as customer_count,
        COUNT(DISTINCT CASE WHEN pay.status = 'paid' AND pay.date = p_date THEN c.id END) as paid_count,
        COUNT(DISTINCT CASE WHEN pay.status = 'not_paid' AND pay.date = p_date THEN c.id END) as not_paid_count,
        COUNT(DISTINCT CASE WHEN pay.promised_date = p_date THEN c.id END) as promised_count,
        (SELECT COALESCE(SUM(l.daily_amount), 0) 
         FROM public.customers c2 
         JOIN public.loans l ON l.customer_id = c2.id 
         WHERE c2.assigned_agent_id = ur.user_id 
           AND c2.is_deleted = FALSE 
           AND l.status = 'active' 
           AND l.is_deleted = FALSE) as total_target
    FROM public.user_roles ur
    JOIN public.profiles p ON p.user_id = ur.user_id AND p.is_deleted = FALSE
    LEFT JOIN public.customers c ON c.assigned_agent_id = ur.user_id AND c.is_deleted = FALSE AND c.status = 'active'
    LEFT JOIN public.payments pay ON pay.customer_id = c.id AND pay.is_deleted = FALSE
    WHERE ur.role IN ('agent', 'manager') AND ur.is_active = TRUE
      AND (
        has_role(auth.uid(), 'admin'::app_role)
        OR (has_role(auth.uid(), 'manager'::app_role) AND (
          ur.user_id = auth.uid()
          OR ur.user_id IN (SELECT pr.user_id FROM profiles pr WHERE pr.reporting_to = auth.uid() AND pr.is_deleted = FALSE)
        ))
      )
    GROUP BY ur.user_id, p.name;
$$;


ALTER FUNCTION public.get_agent_daily_stats(p_date date) OWNER TO postgres;

--
-- Name: get_agent_stats_range(date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_agent_stats_range(p_from date DEFAULT CURRENT_DATE, p_to date DEFAULT CURRENT_DATE) RETURNS TABLE(agent_id uuid, agent_name text, total_collected numeric, total_pending numeric, customer_count bigint, paid_count bigint, not_paid_count bigint, promised_count bigint, total_target numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    ur.user_id as agent_id,
    p.name as agent_name,
    COALESCE(SUM(CASE WHEN pay.status = 'paid' AND pay.date >= p_from AND pay.date <= p_to THEN pay.amount ELSE 0 END), 0) as total_collected,
    COALESCE(SUM(CASE WHEN pay.status = 'not_paid' AND pay.date >= p_from AND pay.date <= p_to THEN pay.amount ELSE 0 END), 0) as total_pending,
    COUNT(DISTINCT c.id) as customer_count,
    COUNT(DISTINCT CASE WHEN pay.status = 'paid' AND pay.date >= p_from AND pay.date <= p_to THEN c.id END) as paid_count,
    COUNT(DISTINCT CASE WHEN pay.status = 'not_paid' AND pay.date >= p_from AND pay.date <= p_to THEN c.id END) as not_paid_count,
    COUNT(DISTINCT CASE WHEN pay.promised_date >= p_from AND pay.promised_date <= p_to THEN c.id END) as promised_count,
    -- FIX: Using a subquery to sum daily_amount correctly without duplication from payment joins
    (SELECT COALESCE(SUM(l.daily_amount), 0) 
     FROM public.customers c2 
     JOIN public.loans l ON l.customer_id = c2.id 
     WHERE c2.assigned_agent_id = ur.user_id 
       AND c2.is_deleted = FALSE 
       AND l.status = 'active' 
       AND l.is_deleted = FALSE) as total_target
  FROM public.user_roles ur
  JOIN public.profiles p ON p.user_id = ur.user_id AND p.is_deleted = FALSE
  LEFT JOIN public.customers c ON c.assigned_agent_id = ur.user_id AND c.is_deleted = FALSE AND c.status = 'active'
  LEFT JOIN public.payments pay ON pay.customer_id = c.id AND pay.is_deleted = FALSE
  WHERE ur.role IN ('agent', 'manager') AND ur.is_active = TRUE
    AND (
      has_role(auth.uid(), 'admin'::app_role)
      OR (has_role(auth.uid(), 'manager'::app_role) AND (
        ur.user_id = auth.uid()
        OR ur.user_id IN (SELECT pr.user_id FROM profiles pr WHERE pr.reporting_to = auth.uid() AND pr.is_deleted = FALSE)
      ))
    )
  GROUP BY ur.user_id, p.name;
$$;


ALTER FUNCTION public.get_agent_stats_range(p_from date, p_to date) OWNER TO postgres;

--
-- Name: get_daily_collections(date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_daily_collections(from_date date, to_date date) RETURNS TABLE(date date, total numeric)
    LANGUAGE sql
    AS $$
  select 
    date,
    sum(amount) as total
  from payments
  where date between from_date and to_date
    and status = 'paid'
    and is_deleted = false
  group by date
  order by date;
$$;


ALTER FUNCTION public.get_daily_collections(from_date date, to_date date) OWNER TO postgres;

--
-- Name: get_daily_collections(date, date, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_daily_collections(from_date date, to_date date, customer_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(date date, total numeric)
    LANGUAGE sql
    AS $$
  select 
    date,
    sum(amount) as total
  from payments
  where date between from_date and to_date
    and status = 'paid'
    and is_deleted = false
    and (
      customer_ids is null 
      or customer_id = any(customer_ids)
    )
  group by date
  order by date;
$$;


ALTER FUNCTION public.get_daily_collections(from_date date, to_date date, customer_ids uuid[]) OWNER TO postgres;

